"""Regression test on a real Claude Code stream-json trace (fixtures/generated/, generated by us)."""
import json
import os

from saysdoes.analyze import analyze
from saysdoes.cli import run
from saysdoes.formats import load

from conftest import REPO

TRACE = os.path.join(REPO, "fixtures", "generated", "claude-code-readonly-review.jsonl")


def test_readonly_offline_plan_extracts_both_kinds(capsys):
    trace = load(TRACE)
    assert trace.format == "claude-code"
    report = analyze(trace)
    cs = report.commitments
    assert sorted(c.kind for c in cs) == ["no_network", "read_only"]  # one each: deduplicated per sentence
    by_kind = {c.kind: c for c in cs}
    assert by_kind["read_only"].span_text == "read-only"
    assert by_kind["no_network"].span_text == "offline"
    for c in cs:
        assert c.step_index == 2 and c.confidence == "low"  # visible assistant text
        assert trace.step(2).text[c.char_start:c.char_end] == c.span_text

    assert [a.tool for a in report.actions] == ["Read", "Read"]
    assert report.findings == []
    assert run(["check", TRACE]) == 0
    assert "no contradictions" in capsys.readouterr().out


SCOPE_CHANGE = os.path.join(REPO, "fixtures", "generated", "claude-code-scope-change.jsonl")


def test_scope_change_start_with_read_only_is_temporary(tmp_path, capsys):
    """The prompt said: say you'll start read-only, then (Step 3) the user approves edits: add load_items().

    "I'll start with a read-only look" is explicitly temporary, so it is recorded and shown but not
    enforced: the later Edit is not a contradiction and the exit code is 0.
    """
    trace = load(SCOPE_CHANGE)
    assert trace.format == "claude-code"
    report = analyze(trace)

    assert len(report.commitments) == 1
    c = report.commitments[0]
    assert c.kind == "read_only" and c.span_text == "read-only" and c.temporary
    assert c.step_index == 2 and c.confidence == "low"
    assert "start with a read-only look" in trace.step(2).text
    assert trace.step(2).text[c.char_start:c.char_end] == c.span_text

    assert [a.tool for a in report.actions] == ["Read", "Glob", "Read", "Edit", "Bash"]
    assert report.findings == []

    out_json = tmp_path / "scope.json"
    assert run(["check", SCOPE_CHANGE, "--json", str(out_json)]) == 0
    out = capsys.readouterr().out
    assert "no contradictions" in out
    assert "ℹ temporary read_only  step 2 (assistant text)" in out
    data = json.loads(out_json.read_text())
    assert data["summary"]["temporary_commitments"] == 1 and data["commitments"][0]["temporary"] is True
